shader.code:
// Apollonian Temple: a flight through an impossible building. Space is
// tiled into cells and each cell is turned inside out through a sphere,
// over and over; the result is an endless hall of arches inside arches,
// domes packed with smaller domes, down to dust. The inversion strength
// breathes along the journey, so the architecture keeps growing new
// vaults and swallowing old ones while you fly through its walls of
// light. Fractal after iq's "Apollonian".

#define TAU 6.28318531

float SS;   // inversion strength
vec4 ORB;   // orbit trap of the last map() call

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

float map(vec3 p) {
  float sc = 1.0;
  ORB = vec4(1e3);
  for (int i = 0; i < 7; i++) {
    p = 2.0 * fract(0.5 * p + 0.5) - 1.0;
    float r2 = dot(p, p);
    ORB = min(ORB, vec4(abs(p), r2));
    float k = SS / r2;
    p *= k;
    sc *= k;
  }
  // Thin sheets: the camera can pass straight through them.
  return 0.25 * abs(p.y) / sc;
}

vec3 normalAt(vec3 p, float eps) {
  vec2 e = vec2(1.0, -1.0) * eps;
  return normalize(
    e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) +
    e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx)
  );
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;

  SS = mix(1.05, 1.5, form) + 0.07 * sin(j * 0.041) * (1.0 - 0.5 * form);
  float hue = colour + j * 0.009;

  // The building repeats every 2 units, so the flight is wrapped.
  float fly = j * 0.045;
  vec3 ro = vec3(
    0.9 + 0.35 * sin(j * 0.011),
    0.45 + 0.3 * sin(j * 0.0077 + 1.0),
    mod(fly, 2.0)
  );
  float yaw = 0.5 * sin(j * 0.013);
  float pitch = 0.3 * sin(j * 0.0091);
  vec3 fw = normalize(vec3(sin(yaw), sin(pitch), cos(yaw)));
  vec3 rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw));
  vec3 up = cross(fw, rt);
  p = rot(j * 0.015) * p;
  vec3 rd = normalize(fw + (p.x * rt + p.y * up) * mix(0.6, 1.5, fisheye));

  float t = 0.01;
  float halo = 0.0;
  float hit = 0.0;
  float steps = 0.0;
  for (int i = 0; i < 64; i++) {
    float d = map(ro + rd * t);
    halo += exp(-d * 45.0) * exp(-t * 0.5);
    if (d < 0.0007 * t + 0.0002) {
      hit = 1.0;
      break;
    }
    t += d;
    steps += 1.0;
    if (t > 9.0) break;
  }

  vec3 mist = palette(hue + 0.6) * 0.02;
  vec3 col = mist;
  if (hit > 0.5) {
    vec3 pos = ro + rd * t;
    vec4 orb = ORB;
    vec3 n = normalAt(pos, 0.0006 + 0.0012 * t);
    float facing = abs(dot(n, rd));
    // The orbit trap paints the ornament: where the folding came closest
    // to the cell's axes and centre.
    vec3 base = palette(hue + sqrt(orb.w) * 1.6 + orb.y * 0.7);
    vec3 trim = palette(hue + 0.45 + orb.x * 1.5);
    base = mix(base, base * base * 1.4, 0.6);
    col = base * (0.1 + 0.9 * facing * facing);
    col = mix(col, trim * 1.2, exp(-10.0 * orb.z));
    // Engraving: contour bands of the trap cover every wall in ornament.
    float bands = abs(sin(34.0 * sqrt(orb.w))) * abs(sin(26.0 * orb.y + 9.0 * orb.x));
    col *= 0.25 + 0.95 * smoothstep(0.05, 0.35, bands);
    col += palette(hue + 0.5 + orb.w) * exp(-14.0 * bands) * 0.9 * seams;
    // Seams glow where the trap hugs an axis.
    col += vec3(1.0, 0.8, 0.5) * 1.1 * exp(-45.0 * orb.x) * seams;
    // Crevices: many steps means a cramped corner.
    col *= 1.0 - 0.75 * steps / 64.0;
    col += palette(hue + 0.7) * pow(1.0 - facing, 3.0) * 0.5;
    col = mix(mist, col, exp(-0.11 * t * t));
  }
  col += (palette(hue + 0.3) + 0.2) * halo * 0.009 * mix(0.0, 2.0, glow);

  col = 1.0 - exp(-col * 1.5);
  return clamp(col, 0.0, 1.0);
}
